      position: relative;
      z-index: 1;
      font-size: clamp(1.75rem, 4vw, 3rem);
      font-weight: 800;
      letter-spacing: -1px;
      line-height: 1.15;
    }
    .tagline__text span {
      background: var(--gradient-main);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    /* ===== News ===== */
