    .news-card__thumb-bg--2 {
      background: linear-gradient(135deg, #FF7A00 0%, #FFB366 100%);
    }
    .news-card__thumb-bg--3 {
      background: linear-gradient(135deg, #1E1E2E 0%, #3A3A5C 100%);
    }
    .news-card__thumb-bg--4 {
      background: linear-gradient(135deg, #7638FA 0%, #FF7A00 100%);
