    .news-card__thumb-icon {
      color: rgba(255,255,255,0.85);
      opacity: 0.6;
    }
    .news-card__body { padding: 20px; }
    .news-card__tags {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-bottom: 12px;
    }
    .news-card__tag {
      padding: 4px 10px;
      border-radius: var(--radius-full);
      font-size: 0.6875rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
