    .news-card__tag--tips { background: rgba(255,122,0,0.1); color: var(--orange); }
    .news-card__tag--product { background: rgba(0,0,0,0.06); color: var(--gray-700); }
    .news-card__tag--safety { background: rgba(34,197,94,0.1); color: #16a34a; }
    .news-card__title {
      font-size: 0.9375rem;
      font-weight: 700;
      line-height: 1.4;
      margin-bottom: 10px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .news-card__date {
      font-size: 0.8125rem;
      color: var(--gray-500);
      font-weight: 500;
    }

    @media (max-width: 768px) {
