      .news-card { flex: 0 0 280px; }
    }

    /* ===== CTA Download ===== */
    .cta-download {
      padding: 100px 0;
      background: var(--white);
      text-align: center;
    }
    .cta-download__inner {
      max-width: 600px;
      margin: 0 auto;
    }
    .cta-download__headline {
      font-size: clamp(2rem, 4vw, 3rem);
      font-weight: 800;
      letter-spacing: -1px;
      margin-bottom: 12px;
    }
    .cta-download__sub {
