      display: flex;
      justify-content: center;
      gap: 16px;
      flex-wrap: wrap;
    }
    .store-btn {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      padding: 14px 28px;
      border-radius: var(--radius-md);
      background: var(--black);
      color: var(--white);
