    .footer__brand-desc {
      font-size: 0.875rem;
      color: rgba(255,255,255,0.5);
      line-height: 1.6;
      max-width: 280px;
    }
    .footer__col-title {
      font-size: 0.8125rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1.2px;
      color: rgba(255,255,255,0.4);
      margin-bottom: 16px;
    }
    .footer__col-links a {
      display: block;
      font-size: 0.875rem;
      color: rgba(255,255,255,0.7);
      padding: 5px 0;
      transition: color 0.2s;
    }
    .footer__col-links a:hover { color: var(--white); }
    .footer__external {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      padding: 32px 0;
      border-top: 1px solid rgba(255,255,255,0.08);
      border-bottom: 1px solid rgba(255,255,255,0.08);
      margin-bottom: 32px;
    }
    .footer__external-group {}
    .footer__external-title {
      font-size: 0.6875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: rgba(255,255,255,0.3);
      margin-bottom: 10px;
    }
    .footer__external-links a {
      display: block;
      font-size: 0.8125rem;
      color: rgba(255,255,255,0.6);
      padding: 3px 0;
      transition: color 0.2s;
    }
    .footer__external-links a:hover { color: var(--white); }
    .footer__bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }
    .footer__lang {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 0.8125rem;
      color: rgba(255,255,255,0.5);
      cursor: pointer;
      transition: color 0.2s;
    }
    .footer__lang:hover { color: var(--white); }
    .footer__social {
      display: flex;
      gap: 16px;
    }
    .footer__social a {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.06);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.2s, transform 0.2s;
    }
    .footer__social a:hover { background: rgba(255,255,255,0.12); transform: translateY(-2px); }
    .footer__social svg { width: 18px; height: 18px; fill: rgba(255,255,255,0.7); }
    .footer__legal {
      display: flex;
      gap: 20px;
      flex-wrap: wrap;
    }
    .footer__legal a {
      font-size: 0.75rem;
      color: rgba(255,255,255,0.4);
      transition: color 0.2s;
    }
    .footer__legal a:hover { color: var(--white); }

    @media (max-width: 768px) {
      .footer__grid { grid-template-columns: 1fr 1fr; }
      .footer__external { grid-template-columns: 1fr 1fr; }
      .footer__bottom { flex-direction: column; align-items: flex-start; }
    }
    @media (max-width: 480px) {
      .footer__grid { grid-template-columns: 1fr; }
    }

    /* ===== Animations ===== */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(24px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .animate-in {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 0.6s ease-out, transform 0.6s ease-out;
    }
    .animate-in.visible {
      opacity: 1;
      transform: translateY(0);
    }
  </style>
</head>
